import {trainingSpots,checkTrainingAction} from './simulator-spots.js';
const seats=[{pos:'UTG',x:15,y:24},{pos:'UTG+1',x:35,y:9},{pos:'UTG+2',x:65,y:9},{pos:'LJ',x:85,y:24},{pos:'HJ',x:94,y:52},{pos:'CO',x:80,y:79},{pos:'BTN',x:20,y:79},{pos:'SB',x:6,y:52},{pos:'BB',x:50,y:94}];
const stackBB=[100,85,125,62,110,73,90,48,100];
const bbValue=2;
export function simulatorPage(){return `<div class="simulator-page"><div class="simulator-controls" role="group" aria-label="Unidade dos stacks"><span>EXIBIR STACKS EM</span><div class="simulator-switch"><button type="button" data-stack-unit="bb" aria-pressed="true">BB</button><button type="button" data-stack-unit="chips" aria-pressed="false">FICHAS</button><button type="button" data-stack-unit="money" aria-pressed="false">MOEDA</button></div></div><section class="simulator-table-area" aria-label="Mesa de poker com nove jogadores"><div class="simulator-table"><div class="simulator-felt"><div class="simulator-board-label">BOARD</div><div class="simulator-board"><span>?</span><span>?</span><span>?</span><span>?</span><span>?</span></div><div class="simulator-pot">POTE · 0 BB</div></div></div>${seats.map((seat,i)=>`<div class="simulator-seat " style="--seat-x:${seat.x}%;--seat-y:${seat.y}%"><span class="simulator-seat-name">JOGADOR ${i+1}</span><strong class="simulator-seat-position">${seat.pos}</strong><span class="simulator-stack" data-stack-bb="${stackBB[i]}">${stackBB[i]} BB</span></div>`).join('')}</section><div class="simulator-actions" role="group" aria-label="Ações do jogador">${["CALL","CHECK","FOLD","RAISE","ALL IN","PRÓXIMO"].map(a=>`<button type="button" data-sim-action="${a}">${a}</button>`).join("")}</div><div class="simulator-feedback" aria-live="polite"></div><div class="simulator-legend">9 JOGADORES · BLINDS 1 / 2 · STACKS ILUSTRATIVOS</div><div class="simulator-pokerinno"><strong>POKERINNO EXPLICA</strong><p>Observe as posições e os stacks. Alterne entre BB, fichas e moeda para visualizar a mesma mesa em unidades diferentes. Esta é a tela inicial do simulador; use os botões para experimentar decisões. Os cenários são didáticos, não solves certificados.</p></div></div>`}
export function setupSimulator(root){const page=root.querySelector('.simulator-page');if(!page)return;let index=0;const feedback=page.querySelector('.simulator-feedback');const board=page.querySelectorAll('.simulator-board span');const pot=page.querySelector('.simulator-pot');const legend=page.querySelector('.simulator-legend');const explain=page.querySelector('.simulator-pokerinno p');let selectedUnit='bb';function formatStack(bb){return selectedUnit==='bb'?bb+' BB':selectedUnit==='chips'?(bb*bbValue).toLocaleString('pt-BR')+' FICHAS':(bb*bbValue).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});}function draw(){const s=trainingSpots[index];board.forEach((el,i)=>{el.textContent=s.board[i]||'?';el.classList.toggle('simulator-card-dealt',i<s.board.length)});pot.textContent='POTE · '+s.pot+' BB';legend.textContent='SPOT '+s.id+' / 1500 · '+s.street.toUpperCase()+' · '+s.stack+' BB · '+s.position+' · '+s.hand+' · '+s.heroCards.join(' ');feedback.textContent='Escolha uma ação para continuar.';explain.textContent='Treino didático de decisões e guerra de ranges. Observe posição, stack, mão, board e pote. Estes exemplos não são soluções certificadas do solver.';page.querySelectorAll('[data-sim-action]').forEach(b=>b.disabled=false);page.querySelectorAll('.simulator-seat').forEach((seat,i)=>{const hero=seats[i].pos===s.position;seat.classList.toggle('simulator-hero',hero);seat.classList.toggle('simulator-acting',hero);seat.querySelector('.simulator-seat-name').textContent=hero?'HERÓI':'JOGADOR '+(i+1);const stack=hero?s.stack:stackBB[i];const stackEl=seat.querySelector('.simulator-stack');stackEl.dataset.stackBb=String(stack);stackEl.textContent=formatStack(stack);});}page.querySelectorAll('[data-sim-action]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.simAction==='PRÓXIMO'){index=(index+1)%trainingSpots.length;draw();return;}const s=trainingSpots[index];const result=checkTrainingAction(s,b.dataset.simAction);feedback.textContent='AÇÃO: '+b.dataset.simAction+' · '+result.message;page.querySelectorAll('.simulator-seat').forEach(seat=>seat.classList.remove('simulator-acting'));page.querySelector('.simulator-hero')?.classList.add('simulator-acting');}));draw();page.querySelectorAll('[data-stack-unit]').forEach(button=>button.addEventListener('click',()=>{const unit=button.dataset.stackUnit;selectedUnit=unit;page.querySelectorAll('[data-stack-unit]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));page.querySelectorAll('[data-stack-bb]').forEach(el=>{const bb=Number(el.dataset.stackBb);el.textContent=formatStack(bb)})}))}
